[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$ProjectPath,
    [Parameter(Mandatory=$true)][string]$PilotRoot,
    [Parameter(Mandatory=$true)][string]$PilotPlanPath,
    [Parameter(Mandatory=$true)][string]$ProvenancePath,
    [switch]$BindingSmokeOnly
)

$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
if([string]::IsNullOrWhiteSpace($ProjectPath)-or-not[IO.Path]::IsPathRooted($ProjectPath)){throw 'Gate12R analysis requires an explicit absolute ProjectPath.'}
$ProjectPath=[IO.Path]::GetFullPath($ProjectPath)
if($BindingSmokeOnly){Write-Output("BINDING-SMOKE-PASSED|Analyze-Gate12RPilot|$ProjectPath");exit 0}
$PilotRoot=[IO.Path]::GetFullPath($PilotRoot);$PilotPlanPath=[IO.Path]::GetFullPath($PilotPlanPath);$ProvenancePath=[IO.Path]::GetFullPath($ProvenancePath)
Import-Module (Join-Path $ProjectPath 'Research\Gate12RProcessReusePreparation.psm1') -Force
Import-Module (Join-Path $ProjectPath 'Research\Gate10RProcessReusePreparation.psm1') -Force
$pilotBase=[IO.Path]::GetFullPath((Join-Path $ProjectPath 'Research\PilotRuns\Gate12R_ProcessReuse_5pct'))
if(-not$PilotRoot.StartsWith($pilotBase.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'PilotRoot is outside Gate12R versioned pilot base.'}
if(Test-Path -LiteralPath (Join-Path $ProjectPath 'Research\FormalRuns\Gate13R_ProcessReuse_5pct\v1')){throw 'Gate13R formal root must remain absent.'}
$plan=Read-Gate12RJson $PilotPlanPath;$provenance=Read-Gate12RJson $ProvenancePath
$executionPath=Join-Path $PilotRoot 'pilot-execution-manifest.json';if(-not(Test-Path $executionPath)){throw 'Pilot execution manifest missing.'};$execution=Read-Gate12RJson $executionPath
if($execution.completed-ne$true-or$execution.formalCampaign-ne$false-or$execution.excludedFromFormalAnalysis-ne$true){throw 'Pilot execution manifest boundary/completion invalid.'}
$measured=@($execution.entries|Where-Object role -eq 'measured-non-formal-pilot');$cold=@($execution.entries|Where-Object role -eq 'excluded-cold-structural-control');$warmup=@($execution.entries|Where-Object role -eq 'excluded-warmup')
if($measured.Count-ne384-or$cold.Count-ne36-or$warmup.Count-ne8){throw 'Pilot execution cardinality mismatch.'}

$records=New-Object Collections.Generic.List[object];$blockRows=New-Object Collections.Generic.List[object];$structural=New-Object Collections.Generic.List[object]
$coldMap=@{};foreach($entry in $cold){$key=([string]$entry.campaignId)+'|'+([string]$entry.algorithmId);if($coldMap.ContainsKey($key)){throw "Duplicate cold control: $key"};$coldMap[$key]=[IO.Path]::GetFullPath((Join-Path $ProjectPath ([string]$entry.outputRelativePath).Replace('/','\')))}
foreach($entry in $measured){
    $output=[IO.Path]::GetFullPath((Join-Path $ProjectPath ([string]$entry.outputRelativePath).Replace('/','\')));$manifestPath=Join-Path $output 'block-manifest.json'
    if(-not(Test-Path $manifestPath)-or(Get-Gate12RLowerSha256 $manifestPath)-ne[string]$entry.blockManifestSha256){throw "Measured block manifest hash mismatch: $($entry.blockId)"}
    $manifest=Read-Gate12RJson $manifestPath;if($manifest.completed-ne$true-or$manifest.formalCampaign-ne$false-or$manifest.hardMemoryRulesPassed-ne$true){throw "Measured block invalid: $($entry.blockId)"}
    $row=New-Object Collections.Generic.List[double]
    foreach($sample in @($manifest.samples|Sort-Object position)){
        $resultPath=Join-Path $output ([string]$sample.workloadResultRelativePath).Replace('/','\');$result=Read-Gate12RJson $resultPath;$endpoint=[double]$result.dynamicHandlingMillisecondsPerScheduledEvent
        if($result.completed-ne$true-or[double]::IsNaN($endpoint)-or[double]::IsInfinity($endpoint)-or$endpoint-le0){throw "Non-positive/non-finite primary endpoint: $($sample.runId)"}
        $row.Add([math]::Log($endpoint))
        $record=[pscustomobject][ordered]@{campaignId=[string]$entry.campaignId;scenarioId=[string]$entry.scenarioId;comparisonCohortId=[string]$entry.comparisonCohortId;block=[int]$entry.block;wave=[int]$entry.wave;waveSlot=[int]$entry.waveSlot;blockId=[string]$entry.blockId;processId=[int]$manifest.processId;algorithmId=[string]$sample.algorithmId;position=[int]$sample.position;predecessorAlgorithmId=[string]$sample.predecessorAlgorithmId;endpoint=$endpoint;logEndpoint=[math]::Log($endpoint);processAgeBeforeMilliseconds=[double]$sample.processAgeBeforeMilliseconds;processAgeAfterCleanupMilliseconds=[double]$sample.processAgeAfterCleanupMilliseconds;workingSetBeforeBytes=[long]$sample.workingSetBeforeBytes;workingSetRawAfterBytes=[long]$sample.workingSetRawAfterBytes;workingSetAfterCleanupBytes=[long]$sample.workingSetAfterCleanupBytes;privateMemoryBeforeBytes=[long]$sample.privateMemoryBeforeBytes;privateMemoryRawAfterBytes=[long]$sample.privateMemoryRawAfterBytes;privateMemoryAfterCleanupBytes=[long]$sample.privateMemoryAfterCleanupBytes;managedMemoryBeforeBytes=[long]$sample.managedMemoryBeforeBytes;managedMemoryRawAfterBytes=[long]$sample.managedMemoryRawAfterBytes;managedMemoryAfterCleanupBytes=[long]$sample.managedMemoryAfterCleanupBytes;sampleRetainedManagedGrowthBytes=[long]$sample.sampleRetainedManagedGrowthBytes;gcCollectionDelta0=[int]$sample.gcCollectionDelta0;gcCollectionDelta1=[int]$sample.gcCollectionDelta1;gcCollectionDelta2=[int]$sample.gcCollectionDelta2;resultRelativePath=Get-Gate12RProjectRelativePath $ProjectPath $resultPath;resultSha256=Get-Gate12RLowerSha256 $resultPath}
        $records.Add($record)
        $key=([string]$entry.campaignId)+'|'+([string]$sample.algorithmId);if(-not$coldMap.ContainsKey($key)){throw "Cold reference missing: $key"};$reference=Read-Gate12RJson (Join-Path ([string]$coldMap[$key]) 'workload-result.json');$comparison=Compare-Gate10RStructuralResults -Reference $reference -Candidate $result;$structural.Add([pscustomobject][ordered]@{campaignId=[string]$entry.campaignId;block=[int]$entry.block;algorithmId=[string]$sample.algorithmId;referenceProjectionSha256=$comparison.referenceProjectionSha256;candidateProjectionSha256=$comparison.candidateProjectionSha256;passed=$comparison.passed});if($comparison.passed-ne$true){throw "Measured/cold structural mismatch: $key block $($entry.block)"}
    }
    $blockRows.Add([pscustomobject][ordered]@{campaignId=[string]$entry.campaignId;comparisonCohortId=[string]$entry.comparisonCohortId;block=[int]$entry.block;values=$row.ToArray();wallSeconds=[double]$entry.wallSeconds;rawBytes=[long]$entry.rawBytes;blockRetainedManagedGrowthBytes=[long]$manifest.blockRetainedManagedGrowthBytes;blockWorkingSetGrowthBytes=[long]$manifest.blockWorkingSetGrowthBytes;blockPrivateMemoryGrowthBytes=[long]$manifest.blockPrivateMemoryGrowthBytes})
}
if($records.Count-ne1152-or@($structural|Where-Object passed -ne $true).Count-ne0){throw 'Measured sample/structural comparison cardinality invalid.'}

$cellStats=New-Object Collections.Generic.List[object]
foreach($group in @($records|Group-Object campaignId,algorithmId)){$values=[double[]]@($group.Group|Sort-Object block|ForEach-Object logEndpoint);if($values.Count-ne32){throw "Cell does not contain 32 independent blocks: $($group.Name)"};$sd=Get-Gate12RSampleStandardDeviation $values;$upper=Get-Gate12RSigmaUpper -SampleSd $sd -N $values.Count -Confidence ([double]$plan.precision.sigmaUpperConfidence);$candidate=Get-Gate12RSampleSizeCandidate -SigmaUpper $upper.sigmaUpper -Z ([double]$plan.precision.criticalValue) -RelativeHalfWidth ([double]$plan.precision.relativeHalfWidth) -MinimumBlocks ([int]$plan.precision.minimumBlocks) -CycleMultiple ([int]$plan.precision.cycleMultiple);$first=$group.Group[0];$cellStats.Add([pscustomobject][ordered]@{statisticKind='marginal-cell-log-sd';campaignId=[string]$first.campaignId;comparisonCohortId=[string]$first.comparisonCohortId;algorithmId=[string]$first.algorithmId;n=$values.Count;meanLog=Get-Gate12RMean $values;sampleLogSd=$sd;sigmaUpper=$upper.sigmaUpper;chiSquareQuantile=$upper.chiSquareQuantile;nRaw=[long]$candidate.nRaw;candidateNFormal=[long]$candidate.candidateNFormal;hardCap=$null})}

$contrasts=New-Object Collections.Generic.List[object]
foreach($campaignGroup in @($records|Group-Object campaignId)){
    $first=$campaignGroup.Group[0];$pairs=New-Object Collections.Generic.List[object]
    if([string]$first.comparisonCohortId-in@('four-algorithm-shared-goal-v1','per-agent-heterogeneous-goal-v1')){$pairs.Add([pscustomobject]@{id='D*L-minus-A*-R';left='D*L';right='A*-R'})}
    if([string]$first.comparisonCohortId-in@('four-algorithm-shared-goal-v1','grouped-field-heterogeneous-goal-v1')){$pairs.Add([pscustomobject]@{id='IDFF-minus-C-FF';left='IDFF';right='C-FF'})}
    foreach($pair in $pairs){$diffs=New-Object Collections.Generic.List[double];foreach($block in 1..32){$left=@($campaignGroup.Group|Where-Object {$_.block-eq$block-and$_.algorithmId-eq$pair.left});$right=@($campaignGroup.Group|Where-Object {$_.block-eq$block-and$_.algorithmId-eq$pair.right});if($left.Count-ne1-or$right.Count-ne1){throw "Paired contrast cardinality invalid: $($campaignGroup.Name)/$block/$($pair.id)"};$diffs.Add([double]$left[0].logEndpoint-[double]$right[0].logEndpoint)};$sd=Get-Gate12RSampleStandardDeviation $diffs.ToArray();$upper=Get-Gate12RSigmaUpper -SampleSd $sd -N $diffs.Count -Confidence ([double]$plan.precision.sigmaUpperConfidence);$candidate=Get-Gate12RSampleSizeCandidate -SigmaUpper $upper.sigmaUpper -Z ([double]$plan.precision.criticalValue) -RelativeHalfWidth ([double]$plan.precision.relativeHalfWidth) -MinimumBlocks ([int]$plan.precision.minimumBlocks) -CycleMultiple ([int]$plan.precision.cycleMultiple);$contrasts.Add([pscustomobject][ordered]@{statisticKind='paired-block-log-difference-sd';campaignId=[string]$first.campaignId;comparisonCohortId=[string]$first.comparisonCohortId;contrastId=[string]$pair.id;n=$diffs.Count;meanLogDifference=Get-Gate12RMean $diffs.ToArray();sampleLogDifferenceSd=$sd;sigmaUpper=$upper.sigmaUpper;chiSquareQuantile=$upper.chiSquareQuantile;nRaw=[long]$candidate.nRaw;candidateNFormal=[long]$candidate.candidateNFormal;hardCap=$null})}
}

$cohortCandidates=New-Object Collections.Generic.List[object]
foreach($cohort in @('four-algorithm-shared-goal-v1','per-agent-heterogeneous-goal-v1','grouped-field-heterogeneous-goal-v1')){$eligible=@($cellStats|Where-Object comparisonCohortId -eq $cohort)+@($contrasts|Where-Object comparisonCohortId -eq $cohort);$max=[long](($eligible|Measure-Object candidateNFormal -Maximum).Maximum);$driver=@($eligible|Where-Object candidateNFormal -eq $max|Select-Object -First 1)[0];$cohortCandidates.Add([pscustomobject][ordered]@{comparisonCohortId=$cohort;candidateNFormal=$max;minimumBlocks=32;cycleMultiple=4;hardCap=$null;driverKind=[string]$driver.statisticKind;driverCampaignId=[string]$driver.campaignId;driverAlgorithmId=if($driver.PSObject.Properties.Name-contains'algorithmId'){[string]$driver.algorithmId}else{$null};driverContrastId=if($driver.PSObject.Properties.Name-contains'contrastId'){[string]$driver.contrastId}else{$null};sigmaUpper=[double]$driver.sigmaUpper})}

$campaignDiagnostics=New-Object Collections.Generic.List[object]
foreach($campaignGroup in @($records|Group-Object campaignId)){$first=$campaignGroup.Group[0];$algorithms=@(Get-Gate12RCohortAlgorithms $first.comparisonCohortId);$rows=New-Object Collections.Generic.List[double[]];foreach($block in 1..32){$vector=New-Object Collections.Generic.List[double];foreach($algorithm in $algorithms){$sample=@($campaignGroup.Group|Where-Object {$_.block-eq$block-and$_.algorithmId-eq$algorithm});$vector.Add([double]$sample[0].logEndpoint)};$rows.Add($vector.ToArray())};$icc=Get-Gate12RConsistencyIcc -Rows $rows.ToArray();$pairwise=New-Object Collections.Generic.List[object];for($a=0;$a-lt$algorithms.Count;$a++){for($b=$a+1;$b-lt$algorithms.Count;$b++){$x=[double[]]@($campaignGroup.Group|Where-Object algorithmId -eq $algorithms[$a]|Sort-Object block|ForEach-Object logEndpoint);$y=[double[]]@($campaignGroup.Group|Where-Object algorithmId -eq $algorithms[$b]|Sort-Object block|ForEach-Object logEndpoint);$pairwise.Add([pscustomobject]@{left=$algorithms[$a];right=$algorithms[$b];pearson=Get-Gate12RPearsonCorrelation $x $y;spearman=Get-Gate12RSpearmanCorrelation $x $y})};};$campaignDiagnostics.Add([pscustomobject][ordered]@{campaignId=[string]$first.campaignId;comparisonCohortId=[string]$first.comparisonCohortId;icc=$icc;pairwise=$pairwise.ToArray()})}

$positionDiagnostics=New-Object Collections.Generic.List[object];foreach($g in @($records|Group-Object algorithmId,position)){$positionDiagnostics.Add([pscustomobject]@{algorithmAndPosition=$g.Name;n=$g.Count;meanLogEndpoint=Get-Gate12RMean ([double[]]@($g.Group|ForEach-Object logEndpoint))})}
$predecessorDiagnostics=New-Object Collections.Generic.List[object];foreach($g in @($records|Group-Object algorithmId,predecessorAlgorithmId)){$predecessorDiagnostics.Add([pscustomobject]@{algorithmAndPredecessor=$g.Name;n=$g.Count;meanLogEndpoint=Get-Gate12RMean ([double[]]@($g.Group|ForEach-Object logEndpoint))})}
$age=[double[]]@($records|ForEach-Object processAgeBeforeMilliseconds);$log=[double[]]@($records|ForEach-Object logEndpoint);$wave=[double[]]@($records|ForEach-Object wave);$gc2=[double[]]@($records|ForEach-Object gcCollectionDelta2)
$globalDiagnostics=[ordered]@{processAgePearsonLogEndpoint=Get-Gate12RPearsonCorrelation $age $log;processAgeSpearmanLogEndpoint=Get-Gate12RSpearmanCorrelation $age $log;waveJitCacheProxySpearmanLogEndpoint=Get-Gate12RSpearmanCorrelation $wave $log;gcGen2PearsonLogEndpoint=Get-Gate12RPearsonCorrelation $gc2 $log;positionGroups=$positionDiagnostics.ToArray();predecessorGroups=$predecessorDiagnostics.ToArray();campaigns=$campaignDiagnostics.ToArray()}

$budgetRows=New-Object Collections.Generic.List[object];$available=(New-Object IO.DriveInfo ([IO.Path]::GetPathRoot($PilotRoot))).AvailableFreeSpace
foreach($candidate in $cohortCandidates){$cohort=[string]$candidate.comparisonCohortId;$blocks=@($blockRows|Where-Object comparisonCohortId -eq $cohort);$wall=[double[]]@($blocks|ForEach-Object wallSeconds);$bytes=[double[]]@($blocks|ForEach-Object rawBytes);$count=[int]$plan.formalProjectionCampaignCounts.$cohort;if($count-eq0){switch($cohort){'four-algorithm-shared-goal-v1'{$count=32};'per-agent-heterogeneous-goal-v1'{$count=21};'grouped-field-heterogeneous-goal-v1'{$count=21}}};$p50w=Get-Gate12RNearestRankPercentile $wall 0.50;$p95w=Get-Gate12RNearestRankPercentile $wall 0.95;$p50b=Get-Gate12RNearestRankPercentile $bytes 0.50;$p95b=Get-Gate12RNearestRankPercentile $bytes 0.95;$processes=[long]$count*[long]$candidate.candidateNFormal;$projected=[long][math]::Ceiling($processes*$p95b*[double]$plan.storageFeasibility.p95SafetyMultiplier);$required=$projected+[long]$plan.storageFeasibility.freeSpaceReserveBytes;$budgetRows.Add([pscustomobject][ordered]@{comparisonCohortId=$cohort;campaignCount=$count;candidateNFormal=[long]$candidate.candidateNFormal;projectedBlockProcesses=$processes;p50BlockWallSeconds=$p50w;p95BlockWallSeconds=$p95w;projectedWallSecondsAtP50=$processes*$p50w;projectedWallSecondsAtP95=$processes*$p95w;p50BlockRawBytes=[long]$p50b;p95BlockRawBytes=[long]$p95b;projectedRawBytesWithSafety=$projected;requiredFreeBytesIncludingReserve=$required;availableFreeBytes=$available;storageFeasible=$available-ge$required})}
$storagePassed=@($budgetRows|Where-Object storageFeasible -ne $true).Count-eq0

$analysis=[ordered]@{schemaVersion=1;analysisKind='gate12r-block-aware-process-reuse-pilot-analysis-v1';completedAtUtc=[DateTime]::UtcNow.ToString('o');primaryEndpoint=[string]$plan.precision.endpoint;transform=[string]$plan.precision.transform;independentUnit='fresh-unity-process-per-complete-williams-block';measuredBlockCount=$measured.Count;measuredSampleCount=$records.Count;structuralComparisonCount=$structural.Count;structuralMismatchCount=@($structural|Where-Object passed -ne $true).Count;cellStatistics=$cellStats.ToArray();pairedContrasts=$contrasts.ToArray();cohortCandidates=$cohortCandidates.ToArray();hardCap=$null;formalCampaign=$false;excludedFromFormalAnalysis=$true;passed=$true}
$correlation=[ordered]@{schemaVersion=1;diagnosticKind='gate12r-block-position-predecessor-process-age-correlation-diagnostics-v1';completedAtUtc=[DateTime]::UtcNow.ToString('o');diagnostics=$globalDiagnostics;interpretation='diagnostic-only-block-cluster-aware';passed=$true}
$budget=[ordered]@{schemaVersion=1;resultKind='gate12r-formal-budget-storage-projection-v1';completedAtUtc=[DateTime]::UtcNow.ToString('o');rows=$budgetRows.ToArray();availableFreeBytes=$available;reserveBytes=[long]$plan.storageFeasibility.freeSpaceReserveBytes;p95SafetyMultiplier=[double]$plan.storageFeasibility.p95SafetyMultiplier;storageFeasible=$storagePassed;wallTimeIsEstimateOnly=$true;passed=$storagePassed}
$candidateDocument=[ordered]@{schemaVersion=1;candidateKind='gate12r-uncapped-5pct-candidate-n-formal-v1';completedAtUtc=[DateTime]::UtcNow.ToString('o');precisionTargetRelativeHalfWidth=0.05;sigmaUpperConfidence=0.90;minimumBlocks=32;cycleMultiple=4;hardCap=$null;cohorts=$cohortCandidates.ToArray();formalExecutionAuthorized=$false;passed=$true}
Write-Gate12RAtomicUtf8NoBomJson -Path (Join-Path $PilotRoot 'block-aware-analysis.json') -Value $analysis -Depth 50
Write-Gate12RAtomicUtf8NoBomJson -Path (Join-Path $PilotRoot 'correlation-diagnostics.json') -Value $correlation -Depth 50
Write-Gate12RAtomicUtf8NoBomJson -Path (Join-Path $PilotRoot 'budget-storage-projection.json') -Value $budget -Depth 30
Write-Gate12RAtomicUtf8NoBomJson -Path (Join-Path $PilotRoot 'candidate-n-formal.json') -Value $candidateDocument -Depth 30
if(-not$storagePassed){throw 'Formal storage projection is not feasible under the frozen p95 safety rule.'}
$manifest=[ordered]@{schemaVersion=1;manifestKind='gate12r-process-reuse-5pct-pilot-manifest-v1';completedAtUtc=[DateTime]::UtcNow.ToString('o');pilotPlanSha256=Get-Gate12RLowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate12RLowerSha256 $ProvenancePath;executionManifestSha256=Get-Gate12RLowerSha256 $executionPath;analysisSha256=Get-Gate12RLowerSha256 (Join-Path $PilotRoot 'block-aware-analysis.json');correlationDiagnosticsSha256=Get-Gate12RLowerSha256 (Join-Path $PilotRoot 'correlation-diagnostics.json');budgetStorageSha256=Get-Gate12RLowerSha256 (Join-Path $PilotRoot 'budget-storage-projection.json');candidateNFormalSha256=Get-Gate12RLowerSha256 (Join-Path $PilotRoot 'candidate-n-formal.json');measuredBlockCount=$measured.Count;measuredSampleCount=$records.Count;coldStructuralControlCount=$cold.Count;warmupBlockCount=$warmup.Count;candidateNFormal=$cohortCandidates.ToArray();storageFeasible=$storagePassed;formalCampaign=$false;excludedFromFormalAnalysis=$true;gate13rAuthorized=$false;formalExecutionAuthorized=$false;completed=$true}
Write-Gate12RAtomicUtf8NoBomJson -Path (Join-Path $PilotRoot 'pilot-manifest.json') -Value $manifest -Depth 30
Write-Host 'Gate12R block-aware pilot analysis passed.' -ForegroundColor Green
exit 0
